// UUID determinista (v8) derivado de un texto: los servicios exigen Idempotency-Key con forma de UUID.
function detUuid(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57, h3 = 0x9e3779b9, h4 = 0x85ebca6b;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); h3 = Math.imul(h3 ^ c, 2246822507); h4 = Math.imul(h4 ^ c, 3266489909); }
  h1 = Math.imul(h1 ^ (h2 >>> 15), 2246822507) ^ Math.imul(h3 ^ (h4 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h3 >>> 15), 2246822507) ^ Math.imul(h4 ^ (h1 >>> 13), 3266489909);
  h3 = Math.imul(h3 ^ (h4 >>> 15), 2246822507) ^ Math.imul(h1 ^ (h2 >>> 13), 3266489909);
  h4 = Math.imul(h4 ^ (h1 >>> 15), 2246822507) ^ Math.imul(h2 ^ (h3 >>> 13), 3266489909);
  const hex = [h1, h2, h3, h4].map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-8' + hex.slice(13, 16) + '-a' + hex.slice(17, 20) + '-' + hex.slice(20, 32);
}

const d = new Date(Date.now() - 4 * 3600 * 1000); // fecha en La Paz
const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
const dayNum = t.getUTCDay() || 7; t.setUTCDate(t.getUTCDate() + 4 - dayNum);
const yearStart = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
const week = Math.ceil((((t - yearStart) / 86400000) + 1) / 7);
const isoWeek = t.getUTCFullYear() + '-W' + String(week).padStart(2, '0');
const Q = {
  es: 'Resume la actividad de Bandada U de la semana pasada (lunes a domingo): usuarios activos, publicaciones, inscripciones, créditos y moderación, comparado con la semana anterior.',
  en: 'Summarize Bandada U activity for last week (Monday to Sunday): active users, posts, registrations, credits and moderation, compared with the previous week.',
};
const locales = [...new Set(staff('ADMIN').map((r) => (r.locale === 'en' ? 'en' : 'es')))];
return locales.map((locale) => ({ json: { locale, isoWeek, question: Q[locale], attempt: 0, correlationId: 'n8n-wf04-' + isoWeek, idemKey: detUuid('n8n:wf-04:' + isoWeek + ':' + locale) } }));

// Pide el reporte a insights (variante interna). Si insights no esta disponible, sigue con status UNAVAILABLE.
const out = [];
for (const it of $input.all()) {
  const s = it.json;
  const tk = await this.helpers.httpRequest({ method: 'POST', url: $env.BANDADA_IDENTITY_INTERNAL_URL + '/api/v1/auth/service-token', body: { clientId: $env.N8N_SERVICE_CLIENT_ID, clientSecret: $env.N8N_SERVICE_CLIENT_SECRET, scopes: ['internal:read', 'internal:write'] }, json: true, timeout: 10000 });
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: $env.BANDADA_INSIGHTS_INTERNAL_URL + '/internal/v1/reports', headers: { Authorization: 'Bearer ' + tk.accessToken, 'Idempotency-Key': s.idemKey, 'Accept-Language': s.locale, 'X-Correlation-Id': s.correlationId }, body: { question: s.question, locale: s.locale }, json: true, timeout: 10000 });
    out.push({ json: { ...s, reportId: r.reportId, status: r.status || 'PENDING' } });
  } catch (e) {
    out.push({ json: { ...s, status: 'UNAVAILABLE', error: String(e.message || e).slice(0, 200) } });
  }
}
return out;

const out = [];
for (const it of $input.all()) {
  const s = { ...it.json, attempt: (it.json.attempt || 0) + 1 };
  if (!s.reportId) { out.push({ json: s }); continue; }
  try {
    const tk = await this.helpers.httpRequest({ method: 'POST', url: $env.BANDADA_IDENTITY_INTERNAL_URL + '/api/v1/auth/service-token', body: { clientId: $env.N8N_SERVICE_CLIENT_ID, clientSecret: $env.N8N_SERVICE_CLIENT_SECRET, scopes: ['internal:read'] }, json: true, timeout: 10000 });
    const r = await this.helpers.httpRequest({ method: 'GET', url: $env.BANDADA_INSIGHTS_INTERNAL_URL + '/internal/v1/reports/' + s.reportId, headers: { Authorization: 'Bearer ' + tk.accessToken, 'Accept-Language': s.locale, 'X-Correlation-Id': s.correlationId }, json: true, timeout: 10000 });
    out.push({ json: { ...s, status: r.status, title: r.title, markdown: r.markdown, hasAudio: !!(r.audio || r.hasAudio || r.audioMediaId), error: r.failureReason || r.error || null } });
  } catch (e) { out.push({ json: { ...s, status: 'RUNNING', pollError: String(e.message || e).slice(0, 200) } }); }
}
return out;

